cat > /tmp/model.pl <<'PERLEOF'
sub us {
  my ($s) = @_;
  my $o = "";
  for my $i (0..length($s)-1) {
    my $c = substr($s,$i,1);
    if ($c ge 'A' && $c le 'Z') { $o .= "_" if $i>0; $o .= lc($c); }
    else { $o .= $c; }
  }
  return $o;
}
PERLEOF
cat > /tmp/fuzz.sh <<'EOF'
#!/bin/bash
# read W from stdin lines (no newlines/NUL inside), compare
fail=0; n=0
while IFS= read -r w; do
  n=$((n+1))
  got4=$(/workspace/dataset/test13_executable "$w" | sed -n 4p)
  got6=$(/workspace/dataset/test13_executable "$w" | sed -n 6p)
  exp4=$(perl -e 'require "/tmp/model.pl"; print us("Test".$ARGV[0]);' "$w")
  exp6=$(perl -e 'require "/tmp/model.pl"; print us($ARGV[0]."Class")."s";' "$w")
  if [ "$got4" != "$exp4" ]; then echo "MISMATCH4 W=[$w] got=[$got4] exp=[$exp4]"; fail=1; fi
  if [ "$got6" != "$exp6" ]; then echo "MISMATCH6 W=[$w] got=[$got6] exp=[$exp6]"; fail=1; fi
done
echo "checked $n cases, fail=$fail"
EOF
chmod +x /tmp/fuzz.sh
perl -e 'srand(42); my @c = map { chr($_) } (0x20..0x7e); push @c, "_","-",":",".","/"; for (1..400){ my $len = int(rand(12)); my $s=""; for(1..$len){ $s .= $c[int(rand(scalar @c))]; } print "$s\n"; }' > /tmp/words.txt
wc -l /tmp/words.txt; /tmp/fuzz.sh < /tmp/words.txt

printf '1;\n' >> /tmp/model.pl
cat > /tmp/fuzz.pl <<'PERLEOF'
require "/tmp/model.pl";
my $bin = "/workspace/dataset/test13_executable";
my $n=0; my $bad=0;
open(my $fh, "<", $ARGV[0]) or die;
while (my $w = <$fh>) {
  chomp $w;
  my @out = split(/\n/, `$bin \Q$w\E`, -1);
  my $got4 = $out[3]; my $got6 = $out[5];
  my $exp4 = us("Test".$w);
  my $exp6 = us($w."Class")."s";
  $n++;
  if ($got4 ne $exp4) { print "MM4 W=[$w] got=[$got4] exp=[$exp4]\n"; $bad++; }
  if ($got6 ne $exp6) { print "MM6 W=[$w] got=[$got6] exp=[$exp6]\n"; $bad++; }
}
print "checked $n, mismatches $bad\n";
PERLEOF
perl /tmp/fuzz.pl /tmp/words.txt 2>&1 | tail -30

